begin;
create table if not exists app.school_settings(tenant_id uuid primary key references app.tenants(id) on delete cascade,legal_name text not null default '',short_name text not null default '',address text not null default '',phone text,email text,logo_object_key text,report_prefix text not null default 'RPT',settings jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),updated_by uuid references authn.users(id));
create table if not exists academics.academic_years(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,name text not null,start_date date,end_date date,is_active boolean not null default false,archived_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,name));
create table if not exists academics.terms(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,academic_year_id uuid not null references academics.academic_years(id) on delete cascade,name text not null,sequence smallint not null check(sequence>0),start_date date,end_date date,is_active boolean not null default false,archived_at timestamptz,unique(tenant_id,academic_year_id,sequence));
create table if not exists academics.classes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,code text not null,name text not null,level_order integer,active boolean not null default true,archived_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists academics.subjects(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,code text not null,name text not null,active boolean not null default true,archived_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists academics.class_subjects(tenant_id uuid not null references app.tenants(id) on delete cascade,class_id uuid not null references academics.classes(id) on delete cascade,subject_id uuid not null references academics.subjects(id) on delete cascade,active boolean not null default true,primary key(class_id,subject_id));
create table if not exists app.staff(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,staff_no text not null,full_name text not null,email text,phone text,job_title text not null default '',staff_type text not null default 'staff',profile_user_id uuid references authn.users(id),active boolean not null default true,archived_at timestamptz,created_at timestamptz not null default now(),created_by uuid references authn.users(id),unique(tenant_id,staff_no));
create table if not exists app.students(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_no text not null,first_name text not null,middle_name text not null default '',last_name text not null,gender text not null default 'unspecified',date_of_birth date,status text not null default 'active' check(status in('active','graduated','withdrawn','suspended')),photo_object_key text,archived_at timestamptz,created_at timestamptz not null default now(),created_by uuid references authn.users(id),search_text text generated always as (lower(student_no||' '||first_name||' '||middle_name||' '||last_name)) stored,unique(tenant_id,student_no));
create index if not exists students_tenant_search_idx on app.students(tenant_id,search_text);
create table if not exists app.guardians(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,full_name text not null,email text,phone text,address text,profile_user_id uuid references authn.users(id),created_at timestamptz not null default now());
create table if not exists app.student_guardians(tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id) on delete cascade,guardian_id uuid not null references app.guardians(id) on delete cascade,relationship text not null,primary key(student_id,guardian_id));
create table if not exists academics.enrollments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),academic_year_id uuid not null references academics.academic_years(id),class_id uuid not null references academics.classes(id),status text not null default 'active',enrolled_at timestamptz not null default now(),ended_at timestamptz,unique(tenant_id,student_id,academic_year_id));
insert into app.schema_migrations(version) values ('0003_school_people') on conflict do nothing;
commit;
